import{positiveId,requireRole}from"../_shared/validate.js";function get(){const id=Number(http.param("id",0));const rows=id>0?db.query("select id, name, role from account where id = ?",[id]):db.query("select id, name, role from account",[]);rows.then(r=>json.ok(r)).catch(e=>json.fail(500,String(e)));}function post(){const b=http.body;if(!b.name){json.fail(400,"name required");return;}const role=(()=>{try{return requireRole(b.role??"user");}catch(e){return"";}})();if(!role){json.fail(400,"role must be admin|user");return;}db.exec("insert into account (name, role) values (?, ?)",[b.name,role]).then(()=>json.ok({created:true})).catch(e=>json.fail(500,String(e)));}function put(){const b=http.body;const id=(()=>{try{return positiveId(b.id);}catch{return 0;}})();if(!id||!b.name){json.fail(400,"id and name required");return;}db.exec("update account set name = ? where id = ?",[b.name,id]).then(()=>json.ok({updated:true})).catch(e=>json.fail(500,String(e)));}function del(){const id=positiveId(http.param("id",0));db.exec("delete from account where id = ?",[id]).then(()=>json.ok({deleted:true})).catch(e=>json.fail(500,String(e)));}function patch(){const b=http.body;const role=requireRole(b.role);db.exec("update account set role = ? where id = ?",[role,positiveId(b.id)]).then(()=>json.ok({patched:true})).catch(e=>json.fail(500,String(e)));}function head(){get();}function options(){json.ok({methods:["get","post","put","del","patch","head","options"]});}export default{get,post,put,del,patch,head,options};